"""Manage the active data-source filter for Paperclip searches.

The server CLI backend accepts a ``-s/--source`` flag per call (e.g. ``pmc``,
``fda``, ``trials``, ``patents``, or country-scoped variants like ``fda/jp``,
``trials/us``). This module lets users pick a subset of top-level sources once,
persist it to ``~/.paperclip/config.json``, and have subsequent
``paperclip search``/``sql`` calls automatically fan out across the selected
sources.

UX mirrors ``paperclip install``: an arrow-key multi-select checkbox on a
TTY, with a numbered fallback for non-interactive shells.
"""

from __future__ import annotations

import json
import re
import shlex
from collections.abc import Iterable

import click

from .. import config

GREEN = "\033[92m"
RED = "\033[91m"
YELLOW = "\033[93m"
CYAN = "\033[96m"
BOLD = "\033[1m"
DIM = "\033[2m"
RESET = "\033[0m"


def _is_prod_server() -> bool:
    """True when connected to the production server (not local/staging)."""
    base = config.get_base_url()
    if "localhost" in base or "127.0.0.1" in base:
        return False
    if "staging" in base:
        return False
    return True


